/* @autogenerated */
import { Injectable, inject } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { Observable } from 'rxjs';
import { ActionParamsDialogComponent } from './action-params-dialog.component';

/** Control con el que se pide un parámetro. */
export type ActionParamType = 'text' | 'textarea' | 'number' | 'boolean' | 'date' | 'datetime' | 'select';

/** Un dato que la acción pide antes de ejecutarse (`<param>` de la acción o de la transición). */
export interface ActionParam {
  /** Clave del valor en el resultado (la propiedad en camelCase si el parámetro se guarda en ella). */
  readonly name: string;
  readonly type: ActionParamType;
  readonly label: string;
  readonly hint?: string;
  readonly required?: boolean;
  /** Valores de un `select`. */
  readonly options?: readonly { readonly value: string; readonly label: string }[];
}

export interface ActionParamsOptions {
  readonly title: string;
  readonly message?: string;
  readonly ok: string;
  readonly cancel: string;
  readonly params: readonly ActionParam[];
}

/** Valores por nombre de parámetro: texto, número, booleano o `Date` (fechas). */
export type ActionParamValues = Record<string, unknown>;

/**
 * Diálogo que pide los parámetros de una acción y hace a la vez de confirmación: emite los valores al aceptar y `null`
 * al cancelar.
 */
@Injectable({ providedIn: 'root' })
export class ActionParamsDialogService {
  private readonly dialog = inject(MatDialog);

  /** Cancelar la suscripción antes de responder cierra el diálogo. */
  ask(options: ActionParamsOptions): Observable<ActionParamValues | null> {
    return new Observable<ActionParamValues | null>((subscriber) => {
      const ref = this.dialog.open(ActionParamsDialogComponent, { data: options, disableClose: true });
      let answered = false;
      const subscription = ref.afterClosed().subscribe((result) => {
        answered = true;
        subscriber.next(result ?? null);
        subscriber.complete();
      });
      return () => {
        subscription.unsubscribe();
        if (!answered) {
          ref.close();
        }
      };
    });
  }
}
